import sqlite3
from datetime import datetime, timezone
from agents import function_tool
DB_PATH = 'claims.db'
VALID_STATUSES = {'open', 'under_review', 'approved', 'denied', 'closed'}


def _archive_closed_claim(conn, claim_id: str) -> None:
    # Move the closed claim's row out of the active table into the archive table
    conn.execute('INSERT INTO claims_archive SELECT * FROM claims WHERE claim_id = ?', (claim_id,))
    conn.execute('DELETE FROM claims WHERE claim_id = ?', (claim_id,))


@function_tool
def update_claim_reserve_and_status(claim_id: str, new_status: str, reserve_amount: float, adjuster_note: str) -> str:
    if not claim_id or not claim_id.startswith('CLM-'):
        return "Error: claim_id must start with 'CLM-'."
    if new_status not in VALID_STATUSES:
        return f'Error: new_status must be one of {sorted(VALID_STATUSES)}.'
    if reserve_amount < 0:
        return 'Error: reserve_amount cannot be negative.'
    if not adjuster_note or not adjuster_note.strip():
        return 'Error: adjuster_note is required.'
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT status, reserve_amount FROM claims WHERE claim_id = ?', (claim_id,)).fetchone()
        if row is None:
            return f'Error: claim {claim_id} not found.'
        old_status, old_reserve = row
        if old_status == 'closed' and new_status != 'closed':
            return 'Error: closed claims cannot be reopened with this tool.'
        now = datetime.now(timezone.utc).isoformat()
        conn.execute('UPDATE claims SET status = ?, reserve_amount = ?, updated_at = ? WHERE claim_id = ?', (new_status, reserve_amount, now, claim_id))
        conn.execute('INSERT INTO claim_history (claim_id, changed_at, old_status, new_status, old_reserve, new_reserve, note) VALUES (?, ?, ?, ?, ?, ?, ?)', (claim_id, now, old_status, new_status, old_reserve, reserve_amount, adjuster_note.strip()))
        if new_status == 'closed':
            _archive_closed_claim(conn, claim_id)
        conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
        return f'Error: database failure: {exc}'
    finally:
        conn.close()
    return f'Claim {claim_id} updated: {old_status} -> {new_status}, reserve {old_reserve} -> {reserve_amount}.'
